// Simple in-memory preference store standing in for a database.
// Stored on globalThis so the value survives dev-server hot reloads.

type PreferenceStore = {
  notificationsEnabled: boolean
}

const globalStore = globalThis as typeof globalThis & {
  __preferenceStore?: PreferenceStore
}

const store: PreferenceStore = (globalStore.__preferenceStore ??= {
  notificationsEnabled: false,
})

export async function getNotificationPreference(): Promise<boolean> {
  return store.notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  store.notificationsEnabled = enabled
}

